double MaxSequence(double nums[], int n)
{
    double high = nums[0];
    double low = nums[0];
    double answer = nums[0];
    for (int i = 1; i < n; ++i) {
        double x = nums[i];
        double p = high * x;
        double q = low * x;
        high = x;
        if (p > high) high = p;
        if (q > high) high = q;
        low = x;
        if (p < low) low = p;
        if (q < low) low = q;
        if (high > answer) answer = high;
    }
    return answer;
}
